import pandas as pd,numpy as np
from scipy.optimize import least_squares
from scipy.signal import lsim, lti
files=['train/A_vref_op1.csv','train/A_amb_op1.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv','train/A_fault_op1.csv']
D=[]
for f in files:
    d=pd.read_csv(f); t=d.time_s.values; dt=t[1]-t[0]
    D.append(dict(t=t,P=d.active_power_pu.values,V=d.voltage_pu.values,th=d.bus_angle_rad.values,vs=d.voltage_setpoint_pu.values,w=d.internal_frequency_dev_rad_s.values,f=f))
def model(p,d):
    T,kf,kv,kth=p[0],p[1],p[2],p[3]
    thd=np.gradient(d['th'],d['t'][1]-d['t'][0])
    sys=lti([1],[abs(T),1]); _,y,_=lsim(sys,thd,d['t'],X0=[thd[0]])
    return d['P'][0]+kf*y+kv*(d['V']-d['V'][0])+kth*(d['th']-d['th'][0])
def res(p): 
    return np.concatenate([model(p,d)-d['P'] for d in D])
r=least_squares(res,[0.05,-0.05,0.02,0.0])
print(r.x, np.std(r.fun))
for d in D: print(d['f'], np.std(model(r.x,d)-d['P']), np.std(d['P']))

import pandas as pd,numpy as np
from scipy.optimize import least_squares
from scipy.signal import lfilter
files=['train/A_vref_op1.csv','train/A_amb_op1.csv','train/A_vref_op3.csv','train/A_gentrip_op1.csv','train/A_load_op2.csv','train/A_line_op3.csv','train/A_fault_op1.csv']
D=[]
for f in files:
    d=pd.read_csv(f)
    D.append(dict(dt=0.001,Q=d.reactive_power_pu.values,V=d.voltage_pu.values,vs=d.voltage_setpoint_pu.values,P=d.active_power_pu.values,f=f))
def lp(u,T,dt):
    a=np.exp(-dt/max(T,1e-4)); y=lfilter([1-a],[1,-a],u-u[0])  # zero-start at u0
    return y
def model(p,d):
    T1,T2,kx,ky,kv,kp=p
    u=d['vs']-d['V']
    y1=lp(u,T1,d['dt']); y2=lp(y1,T2,d['dt'])
    return d['Q'][0]+kx*y1+ky*y2+kv*(d['V']-d['V'][0])+kp*(d['P']-d['P'][0])
def res(p): return np.concatenate([model(p,d)-d['Q'] for d in D])
r=least_squares(res,[0.5,0.05,2.0,0.0,-0.5,0.0],bounds=([0.01,0.001,-20,-20,-20,-20],[20,5,20,20,20,20]))
print(np.round(r.x,4),np.std(r.fun))
for d in D: print(d['f'],np.std(model(r.x,d)-d['Q']),np.std(d['Q']))

